const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const authRouter = require('./routes/auth.routes');
const userRouter = require('./routes/user.routes');
const deploymentRouter = require('./routes/deployment.routes');
const metricsRouter = require('./routes/metrics.routes');
const syncRouter = require('./routes/sync.routes');
const errorMiddleware = require('./middlewares/error.middleware');
const loggerMiddleware = require('./middlewares/logger.middleware');

const app = express();

app.use(helmet());

app.use(cors({
  origin: process.env.CORS_ORIGIN || 'http://localhost:3000',
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

const limiter = rateLimit({
  windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS, 10) || 900000,
  max: parseInt(process.env.RATE_LIMIT_MAX, 10) || 100,
  message: {
    message: 'Demasiadas solicitudes desde esta IP, por favor intente nuevamente más tarde.'
  }
});

app.use(limiter);

app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

app.use(loggerMiddleware);

app.get('/api/health', (req, res) => {
  res.status(200).json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

app.use('/api/v1/auth', authRouter);
app.use('/api/v1/users', userRouter);
app.use('/api/v1/deployments', deploymentRouter);
app.use('/api/v1/metrics', metricsRouter);
app.use('/api/v1/sync', syncRouter);

app.use((req, res) => {
  res.status(404).json({
    status: 'error',
    message: 'El recurso solicitado no fue encontrado.',
    path: req.originalUrl
  });
});

app.use((err, req, res, next) => {
  errorMiddleware(err, req, res, next);
});

module.exports = app;

require('dotenv').config();

const http = require('http');
const app = require('./app');
const { initializeDatabase, closeDatabase } = require('./db/database');
const { initializeRedis, closeRedis } = require('./cache/redis');
const { initializeRabbitMQ, closeRabbitMQ } = require('./events/rabbitmq');

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

const server = http.createServer(app);

async function start() {
  try {
    await initializeDatabase();
    console.log('[DB] SQLite connection established and migrations applied.');
  } catch (err) {
    console.error('[DB] Fatal: Failed to initialize SQLite database.', err);
    process.exit(1);
  }

  try {
    await initializeRedis();
    console.log('[Redis] Connection established.');
  } catch (err) {
    console.error('[Redis] Warning: Failed to connect to Redis. Running without cache.', err);
  }

  try {
    await initializeRabbitMQ();
    console.log('[RabbitMQ] Connection and channel established.');
  } catch (err) {
    console.error('[RabbitMQ] Warning: Failed to connect to RabbitMQ. Events will not be published.', err);
  }

  server.listen(PORT, () => {
    console.log(`[Server] Running on port ${PORT} | ENV: ${NODE_ENV}`);
  });
}

async function shutdown(signal) {
  console.log(`[Server] Received ${signal}. Starting graceful shutdown...`);

  server.close(async (err) => {
    if (err) {
      console.error('[Server] Error closing HTTP server.', err);
    } else {
      console.log('[Server] HTTP server closed. No longer accepting connections.');
    }

    try {
      await closeRabbitMQ();
      console.log('[RabbitMQ] Connection closed.');
    } catch (rabbitErr) {
      console.error('[RabbitMQ] Error closing connection.', rabbitErr);
    }

    try {
      await closeRedis();
      console.log('[Redis] Connection closed.');
    } catch (redisErr) {
      console.error('[Redis] Error closing connection.', redisErr);
    }

    try {
      await closeDatabase();
      console.log('[DB] SQLite connection closed.');
    } catch (dbErr) {
      console.error('[DB] Error closing SQLite connection.', dbErr);
      process.exit(1);
    }

    process.exit(0);
  });
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

process.on('uncaughtException', (err) => {
  console.error('[Process] Uncaught Exception. Shutting down.', err);
  process.exit(1);
});

process.on('unhandledRejection', (reason) => {
  console.error('[Process] Unhandled Rejection. Shutting down.', reason);
  process.exit(1);
});

start().catch((err) => {
  console.error('[Server] Fatal error during startup.', err);
  process.exit(1);
});

module.exports = server;

const Database = require('better-sqlite3');
const path = require('path');
const fs = require('fs');

const NODE_ENV = process.env.NODE_ENV;
const DATABASE_PATH = process.env.DATABASE_PATH
  ? process.env.DATABASE_PATH
  : path.resolve('./data/database.sqlite');

let db;

try {
  if (NODE_ENV === 'test') {
    const verboseOption = NODE_ENV === 'development' ? console.log : undefined;
    db = new Database(':memory:', {
      ...(verboseOption && { verbose: verboseOption }),
    });
  } else {
    const dbDir = path.dirname(DATABASE_PATH);
    if (!fs.existsSync(dbDir)) {
      fs.mkdirSync(dbDir, { recursive: true });
    }

    const verboseOption = NODE_ENV === 'development' ? console.log : undefined;
    db = new Database(DATABASE_PATH, {
      ...(verboseOption && { verbose: verboseOption }),
    });
  }

  db.pragma('journal_mode = WAL');
  db.pragma('foreign_keys = ON');
  db.pragma('synchronous = NORMAL');
  db.pragma('cache_size = -64000');
  db.pragma('temp_store = MEMORY');

  db.exec(`
    CREATE TABLE IF NOT EXISTS users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      username TEXT NOT NULL UNIQUE,
      email TEXT NOT NULL UNIQUE,
      password_hash TEXT NOT NULL,
      role TEXT NOT NULL DEFAULT 'user' CHECK(role IN ('admin', 'user')),
      is_active INTEGER NOT NULL DEFAULT 1,
      created_at TEXT NOT NULL DEFAULT (datetime('now')),
      updated_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
  `);

  db.exec(`
    CREATE TABLE IF NOT EXISTS deployments (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      id_app TEXT NOT NULL,
      status TEXT NOT NULL CHECK(status IN ('SUCCESS', 'FAILED', 'IN_PROGRESS')),
      deployment_time INTEGER NOT NULL,
      deployed_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
      created_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
  `);

  db.exec(`
    CREATE INDEX IF NOT EXISTS idx_deployments_id_app ON deployments(id_app);
  `);
} catch (error) {
  console.error('Error initializing database:', error);
  process.exit(1);
}

function closeDatabase() {
  db.close();
}

module.exports = { db, closeDatabase };

const Redis = require('ioredis');

const REDIS_HOST = process.env.REDIS_HOST || 'localhost';
const REDIS_PORT = parseInt(process.env.REDIS_PORT, 10) || 6379;
const REDIS_PASSWORD = process.env.REDIS_PASSWORD;
const REDIS_DB = parseInt(process.env.REDIS_DB, 10) || 0;
const REDIS_TTL = parseInt(process.env.REDIS_TTL_SECONDS, 10) || 300;

const redisOptions = {
  host: REDIS_HOST,
  port: REDIS_PORT,
  db: REDIS_DB,
  lazyConnect: true,
  maxRetriesPerRequest: 3,
  retryStrategy: (times) => {
    if (times > 10) {
      return null;
    }
    return Math.min(times * 100, 3000);
  },
  enableReadyCheck: true,
  connectTimeout: 10000,
};

if (REDIS_PASSWORD && REDIS_PASSWORD.trim() !== '') {
  redisOptions.password = REDIS_PASSWORD;
}

const redisClient = new Redis(redisOptions);

redisClient.on('connect', () => {
  console.log(`[Redis] Conexión establecida con ${REDIS_HOST}:${REDIS_PORT}`);
});

redisClient.on('ready', () => {
  console.log('[Redis] Cliente listo para recibir comandos.');
});

redisClient.on('error', (err) => {
  console.error(`[Redis] Error en el cliente: ${err.message}`);
});

redisClient.on('close', () => {
  console.warn('[Redis] La conexión a Redis fue cerrada.');
});

redisClient.on('reconnecting', () => {
  console.log('[Redis] Intentando reconectar a Redis...');
});

const connectRedis = async () => {
  try {
    await redisClient.connect();
  } catch (err) {
    console.error(`[Redis] Falló la conexión inicial a Redis: ${err.message}`);
  }
};

const disconnectRedis = async () => {
  try {
    await redisClient.quit();
  } catch (err) {
    console.error(`[Redis] Error al cerrar la conexión a Redis: ${err.message}`);
  }
};

module.exports = {
  redisClient,
  connectRedis,
  disconnectRedis,
  REDIS_TTL,
};

const amqplib = require('amqplib');

const RABBITMQ_URL = process.env.RABBITMQ_URL || 'amqp://localhost';
const RABBITMQ_EXCHANGE = process.env.RABBITMQ_EXCHANGE || 'app_events';
const RABBITMQ_EXCHANGE_TYPE = process.env.RABBITMQ_EXCHANGE_TYPE || 'topic';
const RABBITMQ_RECONNECT_DELAY_MS = parseInt(process.env.RABBITMQ_RECONNECT_DELAY_MS || '5000', 10);
const RABBITMQ_MAX_RECONNECT_ATTEMPTS = parseInt(process.env.RABBITMQ_MAX_RECONNECT_ATTEMPTS || '10', 10);

let connection = null;
let channel = null;
let reconnectAttempts = 0;
let isConnecting = false;

async function connect() {
  if (isConnecting) {
    return;
  }

  isConnecting = true;

  try {
    connection = await amqplib.connect(RABBITMQ_URL);

    channel = await connection.createChannel();

    await channel.assertExchange(RABBITMQ_EXCHANGE, RABBITMQ_EXCHANGE_TYPE, { durable: true });

    reconnectAttempts = 0;
    isConnecting = false;

    console.log('[RabbitMQ] Connection established successfully.');

    connection.on('error', (err) => {
      console.error('[RabbitMQ] Connection error:', err);
      reconnect();
    });

    connection.on('close', () => {
      console.log('[RabbitMQ] Connection closed.');
      reconnect();
    });

    channel.on('error', (err) => {
      console.error('[RabbitMQ] Channel error:', err);
    });

    channel.on('close', () => {
      console.log('[RabbitMQ] Channel closed.');
    });
  } catch (err) {
    isConnecting = false;
    await reconnect(err);
  }
}

async function reconnect(err) {
  reconnectAttempts += 1;

  if (reconnectAttempts > RABBITMQ_MAX_RECONNECT_ATTEMPTS) {
    console.error('[RabbitMQ] Max reconnect attempts reached. Giving up.');
    throw new Error(
      `[RabbitMQ] Failed to reconnect after ${RABBITMQ_MAX_RECONNECT_ATTEMPTS} attempts. Last error: ${err ? err.message : 'unknown'}`
    );
  }

  console.log(`[RabbitMQ] Reconnecting... attempt ${reconnectAttempts} of ${RABBITMQ_MAX_RECONNECT_ATTEMPTS}`);

  await new Promise((resolve) => setTimeout(resolve, RABBITMQ_RECONNECT_DELAY_MS));

  await connect();
}

function getChannel() {
  if (!channel) {
    throw new Error('RabbitMQ channel is not initialized. Call connect() first.');
  }
  return channel;
}

function getConnection() {
  if (!connection) {
    throw new Error('RabbitMQ connection is not initialized. Call connect() first.');
  }
  return connection;
}

async function closeConnection() {
  if (channel) {
    try {
      await channel.close();
      console.log('[RabbitMQ] Channel closed successfully.');
    } catch (err) {
      console.error('[RabbitMQ] Error closing channel:', err);
    }
  }

  if (connection) {
    try {
      await connection.close();
      console.log('[RabbitMQ] Connection closed successfully.');
    } catch (err) {
      console.error('[RabbitMQ] Error closing connection:', err);
    }
  }

  channel = null;
  connection = null;

  console.log('[RabbitMQ] Resources released.');
}

module.exports = {
  connect,
  reconnect,
  getChannel,
  getConnection,
  closeConnection,
};

'use strict';

const dotenv = require('dotenv');

dotenv.config();

const parseIntEnv = (value, defaultValue) => {
  if (value === undefined || value === null || value === '') return defaultValue;
  const parsed = parseInt(value, 10);
  return isNaN(parsed) ? defaultValue : parsed;
};

const parseBoolEnv = (value, defaultValue) => {
  if (value === undefined || value === null || value === '') return defaultValue;
  return value === 'true';
};

const nodeEnv = process.env.NODE_ENV || 'development';

const jwtSecret = process.env.JWT_SECRET;
if (!jwtSecret) {
  throw new Error(
    'Missing required environment variable: JWT_SECRET must be defined and non-empty'
  );
}

const bcryptSaltRounds = parseIntEnv(process.env.BCRYPT_SALT_ROUNDS, 12);

if (nodeEnv === 'production' && bcryptSaltRounds < 12) {
  throw new Error(
    `Invalid value for environment variable BCRYPT_SALT_ROUNDS: received ${bcryptSaltRounds}, must be >= 12 in production`
  );
}

const serverPort = parseIntEnv(process.env.PORT, 3000);

const validateConfig = (config) => {
  const validNodeEnvs = ['development', 'test', 'production'];
  if (!validNodeEnvs.includes(config.server.nodeEnv)) {
    throw new Error(
      `Invalid value for environment variable NODE_ENV: received '${config.server.nodeEnv}', must be one of: ${validNodeEnvs.join(', ')}`
    );
  }

  if (!Number.isInteger(config.server.port) || config.server.port <= 0) {
    throw new Error(
      `Invalid value for environment variable PORT: received '${process.env.PORT}', must be a positive integer`
    );
  }

  if (!config.jwt.secret || config.jwt.secret.trim() === '') {
    throw new Error(
      'Missing required environment variable: JWT_SECRET must be defined and non-empty'
    );
  }

  if (
    config.server.nodeEnv === 'production' &&
    config.bcrypt.saltRounds < 12
  ) {
    throw new Error(
      `Invalid value for environment variable BCRYPT_SALT_ROUNDS: received ${config.bcrypt.saltRounds}, must be >= 12 in production`
    );
  }
};

const corsAllowedOrigins = process.env.CORS_ALLOWED_ORIGINS
  ? process.env.CORS_ALLOWED_ORIGINS.split(',').map((origin) => origin.trim())
  : ['http://localhost:3000'];

const redisPassword = process.env.REDIS_PASSWORD !== undefined && process.env.REDIS_PASSWORD !== ''
  ? process.env.REDIS_PASSWORD
  : undefined;

const config = Object.freeze({
  server: Object.freeze({
    port: serverPort,
    nodeEnv: nodeEnv,
    apiVersion: process.env.API_VERSION || 'v1',
  }),

  database: Object.freeze({
    path: nodeEnv === 'test' ? ':memory:' : (process.env.DB_PATH || './data/database.sqlite'),
    inMemory: nodeEnv === 'test',
  }),

  jwt: Object.freeze({
    secret: jwtSecret,
    expiresIn: process.env.JWT_EXPIRES_IN || '1h',
    algorithm: 'HS256',
  }),

  bcrypt: Object.freeze({
    saltRounds: bcryptSaltRounds,
  }),

  redis: Object.freeze({
    host: process.env.REDIS_HOST || 'localhost',
    port: parseIntEnv(process.env.REDIS_PORT, 6379),
    password: redisPassword,
    ttl: parseIntEnv(process.env.REDIS_TTL_SECONDS, 300),
    enabled: parseBoolEnv(process.env.REDIS_ENABLED, true),
  }),

  rabbitmq: Object.freeze({
    url: process.env.RABBITMQ_URL || 'amqp://localhost',
    exchange: process.env.RABBITMQ_EXCHANGE || 'users.events',
    queue: process.env.RABBITMQ_QUEUE || 'users.sync',
    enabled: parseBoolEnv(process.env.RABBITMQ_ENABLED, true),
  }),

  rateLimit: Object.freeze({
    windowMs: parseIntEnv(process.env.RATE_LIMIT_WINDOW_MS, 900000),
    max: parseIntEnv(process.env.RATE_LIMIT_MAX_REQUESTS, 100),
  }),

  cors: Object.freeze({
    allowedOrigins: Object.freeze(corsAllowedOrigins),
  }),

  logging: Object.freeze({
    level: process.env.LOG_LEVEL || 'info',
  }),
});

validateConfig(config);

module.exports = config;

const { Router } = require('express');
const authRouter = require('./auth/auth.routes');
const userRouter = require('./users/user.routes');
const deploymentRouter = require('./deployments/deployment.routes');
const metricsRouter = require('./metrics/metrics.routes');
const syncRouter = require('./sync/sync.routes');

/**
 * Router agregador principal.
 * Este archivo centraliza y monta todos los sub-routers bajo sus prefijos de versión.
 * Los middlewares globales (helmet, cors, rate-limit, morgan) se configuran en app.js.
 */

const router = Router();

const API_PREFIX = '/api/v1';

router.use(`${API_PREFIX}/auth`, authRouter);
router.use(`${API_PREFIX}/users`, userRouter);
router.use(`${API_PREFIX}/deployments`, deploymentRouter);
router.use(`${API_PREFIX}/metrics`, metricsRouter);
router.use(`${API_PREFIX}/sync`, syncRouter);

router.get('/health', (req, res) => {
    return res.status(200).json({
        status: 'ok',
        timestamp: new Date().toISOString(),
        version: process.env.npm_package_version || '1.0.0'
    });
});

module.exports = router;

const { Router } = require('express');
const { login } = require('../controllers/auth.controller');
const { validate } = require('../middlewares/validate.middleware');
const { loginSchema } = require('../validators/auth.validator');
const { authRateLimiter } = require('../middlewares/rateLimiter.middleware');

/**
 * @module AuthRoutes
 * @description Enrutador del dominio de autenticación.
 * @baseRoute /api/v1/auth
 * @endpoints
 *   POST /login - Autentica las credenciales del usuario y retorna un token JWT.
 */

const router = Router();

router.post('/login', authRateLimiter, validate(loginSchema), login);

module.exports = router;

const { Router } = require('express');
const metricsController = require('../controllers/metrics.controller');
const authMiddleware = require('../middlewares/auth.middleware');
const rbacMiddleware = require('../middlewares/rbac.middleware');
const validateMiddleware = require('../middlewares/validate.middleware');

const router = Router({ mergeParams: true });

router.get(
  '/:id_app',
  authMiddleware,
  rbacMiddleware('admin'),
  validateMiddleware({
    params: {
