const jwt = require('jsonwebtoken');
const bcrypt = require('bcrypt');
const UserRepository = require('../repositories/user.repository');

const DUMMY_HASH = '$2b$12$KIXBp/dummy.hash.for.timing.attack.prevention.only.xxxxx';

if (!process.env.JWT_SECRET) {
  throw new Error('JWT_SECRET environment variable is required but not defined. Service cannot start without it.');
}

async function login(email, password) {
  const user = await UserRepository.findByEmail(email);

  if (!user) {
    await bcrypt.compare(password, DUMMY_HASH);
    const error = new Error('Credenciales inválidas');
    error.statusCode = 401;
    throw error;
  }

  const isPasswordValid = await bcrypt.compare(password, user.password);

  if (!isPasswordValid) {
    const error = new Error('Credenciales inválidas');
    error.statusCode = 401;
    throw error;
  }

  const payload = {
    id: user.id,
    email: user.email,
    rol: user.rol,
  };

  const token = jwt.sign(payload, process.env.JWT_SECRET, {
    expiresIn: process.env.JWT_EXPIRES_IN || '1h',
    algorithm: 'HS256',
  });

  return {
    token,
    user: {
      id: user.id,
      email: user.email,
      rol: user.rol,
    },
  };
}

function validateToken(token) {
  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET, {
      algorithms: ['HS256'],
    });
    return decoded;
  } catch (err) {
    if (err instanceof jwt.TokenExpiredError) {
      const error = new Error('Token expirado');
      error.statusCode = 401;
      throw error;
    }
    if (err instanceof jwt.JsonWebTokenError) {
      const error = new Error('Token inválido');
      error.statusCode = 401;
      throw error;
    }
    throw err;
  }
}

module.exports = {
  login,
  validateToken,
};

const bcrypt = require('bcrypt');
const usersRepositoryDefault = require('../repositories/users.repository');
const cacheClientDefault = require('../cache/redis.client');
const eventPublisherDefault = require('../events/publisher');
const logger = require('../utils/logger');

const SALT_ROUNDS = parseInt(process.env.BCRYPT_SALT_ROUNDS, 10) || 12;
const CACHE_TTL = 300;

class BusinessError extends Error {
  constructor(message, code, status) {
    super(message);
    this.name = 'BusinessError';
    this.code = code;
    this.status = status;
  }
}

class UsersService {
  constructor(
    usersRepository = usersRepositoryDefault,
    cacheClient = cacheClientDefault,
    eventPublisher = eventPublisherDefault
  ) {
    this.usersRepository = usersRepository;
    this.cacheClient = cacheClient;
    this.eventPublisher = eventPublisher;
  }

  _stripPassword(user) {
    if (!user) return user;
    const { password, ...userWithoutPassword } = user;
    return userWithoutPassword;
  }

  _stripPasswordFromArray(users) {
    return users.map((user) => this._stripPassword(user));
  }

  async createUser(userData) {
    const existingUser = await this.usersRepository.findByEmail(userData.email);
    if (existingUser) {
      throw new BusinessError(
        `User with email ${userData.email} already exists`,
        'USER_ALREADY_EXISTS',
        409
      );
    }

    const passwordHash = await bcrypt.hash(userData.password, SALT_ROUNDS);

    const userToCreate = {
      ...userData,
      password: passwordHash,
    };

    const createdUser = await this.usersRepository.create(userToCreate);

    try {
      await this.eventPublisher.publish('user.created', {
        id: createdUser.id,
        email: createdUser.email,
        timestamp: new Date().toISOString(),
      });
    } catch (err) {
      logger.warn('Failed to publish user.created event', { error: err.message, userId: createdUser.id });
    }

    try {
      await this._invalidateListCache();
    } catch (err) {
      logger.warn('Failed to invalidate list cache after createUser', { error: err.message });
    }

    logger.info('User created successfully', { userId: createdUser.id, email: createdUser.email });

    return this._stripPassword(createdUser);
  }

  async getAllUsers(filters = {}) {
    const page = filters.page || 1;
    const limit = filters.limit || 10;
    const search = filters.search || '';

    const cacheKey = `users:list:page:${page}:limit:${limit}:search:${search}`;

    try {
      const cached = await this.cacheClient.get(cacheKey);
      if (cached) {
        logger.info('getAllUsers served from cache', { cacheKey });
        return JSON.parse(cached);
      }
    } catch (err) {
      logger.warn('Cache read failed in getAllUsers', { error: err.message });
    }

    const users = await this.usersRepository.findAll(filters);
    const result = this._stripPasswordFromArray(users);

    try {
      await this.cacheClient.set(cacheKey, JSON.stringify(result), 'EX', CACHE_TTL);
    } catch (err) {
      logger.warn('Cache write failed in getAllUsers', { error: err.message });
    }

    return result;
  }

  async getUserById(id) {
    const cacheKey = `users:id:${id}`;

    try {
      const cached = await this.cacheClient.get(cacheKey);
      if (cached) {
        logger.info('getUserById served from cache', { cacheKey, userId: id });
        return JSON.parse(cached);
      }
    } catch (err) {
      logger.warn('Cache read failed in getUserById', { error: err.message });
    }

    const user = await this.usersRepository.findById(id);
    if (!user) {
      throw new BusinessError(
        `User with id ${id} not found`,
        'USER_NOT_FOUND',
        404
      );
    }

    const userWithoutPassword = this._stripPassword(user);

    try {
      await this.cacheClient.set(cacheKey, JSON.stringify(userWithoutPassword), 'EX', CACHE_TTL);
    } catch (err) {
      logger.warn('Cache write failed in getUserById', { error: err.message });
    }

    return userWithoutPassword;
  }

  async updateUser(id, updateData) {
    await this.getUserById(id);

    const dataToUpdate = { ...updateData };

    if (dataToUpdate.password) {
      dataToUpdate.password = await bcrypt.hash(dataToUpdate.password, SALT_ROUNDS);
    }

    const updatedUser = await this.usersRepository.update(id, dataToUpdate);

    try {
      await this._invalidateUserCache(id);
      await this._invalidateListCache();
    } catch (err) {
      logger.warn('Cache invalidation failed in updateUser', { error: err.message, userId: id });
    }

    const { password, ...eventPayload } = updateData;
    try {
      await this.eventPublisher.publish('user.updated', {
        id,
        updatedFields: eventPayload,
        timestamp: new Date().toISOString(),
      });
    } catch (err) {
      logger.warn('Failed to publish user.updated event', { error: err.message, userId: id });
    }

    logger.info('User updated successfully', { userId: id });

    return this._stripPassword(updatedUser);
  }

  async deleteUser(id) {
    await this.getUserById(id);

    await this.usersRepository.delete(id);

    try {
      await this._invalidateUserCache(id);
      await this._invalidateListCache();
    } catch (err) {
      logger.warn('Cache invalidation failed in deleteUser', { error: err.message, userId: id });
    }

    try {
      await this.eventPublisher.publish('user.deleted', {
        id,
        timestamp: new Date().toISOString(),
      });
    } catch (err) {
      logger.warn('Failed to publish user.deleted event', { error: err.message, userId: id });
    }

    logger.info('User deleted successfully', { userId: id });

    return { deleted: true, id };
  }

  async syncUsers(externalUsers) {
    const summary = { created: 0, updated: 0, unchanged: 0, errors: 0 };

    if (!Array.isArray(externalUsers)) {
      logger.warn('syncUsers received non-array input');
      return summary;
    }

    for (const externalUser of externalUsers) {
      try {
        const existingUser = await this.usersRepository.findByEmail(externalUser.email);

        if (!existingUser) {
          const userToCreate = { ...externalUser };
          if (!userToCreate.password) {
            userToCreate.password = this._generateTemporaryPassword();
          }
          await this.createUser(userToCreate);
          summary.created += 1;
          logger.info('syncUsers: user created', { email: externalUser.email });
        } else {
          const hasChanges = this._detectChanges(existingUser, externalUser);
          if (hasChanges) {
            const updateData = { ...externalUser };
            delete updateData.email;
            await this.updateUser(existingUser.id, updateData);
            summary.updated += 1;
            logger.info('syncUsers: user updated', { email: externalUser.email, userId: existingUser.id });
          } else {
            summary.unchanged += 1;
            logger.info('syncUsers: user unchanged', { email: externalUser.email, userId: existingUser.id });
          }
        }
      } catch (err) {
        summary.errors += 1;
        logger.error('syncUsers: error processing user', { email: externalUser.email, error: err.message });
      }
    }

    logger.info('syncUsers completed', summary);
    return summary;
  }

  _detectChanges(existingUser, externalUser) {
    const fieldsToCompare = ['name', 'role', 'username'];
    return fieldsToCompare.some((field) => {
      if (externalUser[field] === undefined) return false;
      return existingUser[field] !== externalUser[field];
    });
  }

  _generateTemporaryPassword() {
    const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*';
    let password = '';
    for (let i = 0; i < 16; i++) {
      password += chars.charAt(Math.floor(Math.random() * chars.length));
    }
    return password;
  }

  async _invalidateUserCache(id) {
    const cacheKey = `users:id:${id}`;
    await this.cacheClient.del(cacheKey);
  }

  async _invalidateListCache() {
    try {
      const keys = await this.cacheClient.keys('users:list*');
      if (keys && keys.length > 0) {
        await this.cacheClient.del(...keys);
      }
    } catch (err) {
      logger.warn('Failed to invalidate list cache pattern', { error: err.message });
      await this.cacheClient.del('users:list:page:1:limit:10:search:');
    }
  }
}

module.exports = UsersService;

const deploymentsRepository = require('../repositories/deployments.repository');
const rabbitmqClient = require('../events/rabbitmq.client');
const appsRepository = require('../repositories/apps.repository');
const AppError = require('../utils/AppError');

const VALID_STATUSES = ['SUCCESS', 'FAILED', 'IN_PROGRESS'];

class DeploymentsService {
  async registerDeployment(deploymentData) {
    const { id_app, version, status, deployed_by } = deploymentData;

    if (!VALID_STATUSES.includes(status)) {
      throw new AppError(
        `Invalid status '${status}'. Allowed values are: ${VALID_STATUSES.join(', ')}`,
        'INVALID_STATUS',
        400
      );
    }

    const app = await appsRepository.findById(id_app);
    if (!app) {
      throw new AppError(
        `Application with id '${id_app}' not found`,
        'APP_NOT_FOUND',
        404
      );
    }

    const deploymentToCreate = {
      ...deploymentData,
      created_at: new Date().toISOString(),
    };

    const createdDeployment = await deploymentsRepository.create(deploymentToCreate);

    try {
      await rabbitmqClient.publish({
        eventType: 'DEPLOYMENT_REGISTERED',
        payload: createdDeployment,
        timestamp: new Date().toISOString(),
      });
    } catch (rabbitmqError) {
      console.error(
        '[DeploymentsService] Failed to publish DEPLOYMENT_REGISTERED event to RabbitMQ:',
        rabbitmqError.message
      );
    }

    return createdDeployment;
  }

  async getAverageDeploymentTime(id_app) {
    const parsedId = parseInt(id_app, 10);
    if (!id_app || isNaN(parsedId) || parsedId <= 0) {
      throw new AppError(
        `Invalid id_app '${id_app}'. Must be a positive integer.`,
        'INVALID_APP_ID',
        400
      );
    }

    const sevenDaysAgo = new Date();
    sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);

    const deployments = await deploymentsRepository.findSuccessfulByAppIdSince(
      parsedId,
      sevenDaysAgo
    );

    if (!deployments || deployments.length === 0) {
      return {
        id_app: parsedId,
        average_time_seconds: null,
        total_deployments: 0,
        period: 'last_7_days',
        message: 'No successful deployments found in the last 7 days',
      };
    }

    const totalSeconds = deployments.reduce((acc, deployment) => {
      const start = new Date(deployment.start_time).getTime();
      const end = new Date(deployment.end_time).getTime();
      const durationSeconds = (end - start) / 1000;
      return acc + durationSeconds;
    }, 0);

    const averageTimeSeconds = parseFloat(
      (totalSeconds / deployments.length).toFixed(2)
    );

    return {
      id_app: parsedId,
      average_time_seconds: averageTimeSeconds,
      total_deployments: deployments.length,
      period: 'last_7_days',
    };
  }
}

module.exports = new DeploymentsService();

const { AppError } = require('../utils/errors');
const logger = require('../utils/logger');

class MetricsService {
  constructor(deploymentRepository, redisClient = null, eventPublisher = null) {
    this.deploymentRepository = deploymentRepository;
    this.redisClient = redisClient;
    this.eventPublisher = eventPublisher;
  }

  async getAverageDeploymentTime(id_app) {
    if (id_app === null || id_app === undefined || id_app === '') {
      throw new AppError('El parámetro id_app es requerido y no puede estar vacío', 400, 'INVALID_APP_ID');
    }

    const cacheKey = `metrics:avg-time:${id_app}`;

    if (this.redisClient) {
      try {
        const cached = await this.redisClient.get(cacheKey);
        if (cached) {
          logger.info(`[MetricsService] Cache hit para clave ${cacheKey}`);
          return JSON.parse(cached);
        }
      } catch (redisError) {
        logger.error(`[MetricsService] Error al leer de Redis, continuando sin caché: ${redisError.message}`);
      }
    }

    const endDate = new Date();
    const startDate = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);

    const deployments = await this.deploymentRepository.findSuccessfulDeploymentsByAppAndDateRange(
      id_app,
      startDate,
      endDate
    );

    if (!deployments || deployments.length === 0) {
      const emptyResult = {
        appId: id_app,
        averageTime: 0,
        unit: 'seconds',
        totalDeployments: 0,
        periodDays: 7,
        calculatedAt: new Date().toISOString()
      };

      logger.info(`[MetricsService] No se encontraron despliegues exitosos para app ${id_app} en los últimos 7 días`);
      return emptyResult;
    }

    const totalDuration = deployments.reduce((acc, deployment) => {
      let durationSeconds;

      if (deployment.duration_seconds !== undefined && deployment.duration_seconds !== null) {
        durationSeconds = Number(deployment.duration_seconds);
      } else if (deployment.started_at && deployment.finished_at) {
        const startedAt = new Date(deployment.started_at).getTime();
        const finishedAt = new Date(deployment.finished_at).getTime();
        durationSeconds = (finishedAt - startedAt) / 1000;
      } else {
        durationSeconds = 0;
      }

      return acc + durationSeconds;
    }, 0);

    const averageTime = parseFloat((totalDuration / deployments.length).toFixed(2));

    const result = {
      appId: id_app,
      averageTime,
      unit: 'seconds',
      totalDeployments: deployments.length,
      periodDays: 7,
      calculatedAt: new Date().toISOString()
    };

    if (this.redisClient) {
      try {
        await this.redisClient.set(cacheKey, JSON.stringify(result), 'EX', 300);
        logger.info(`[MetricsService] Resultado almacenado en caché con clave ${cacheKey} y TTL 300s`);
      } catch (redisError) {
        logger.error(`[MetricsService] Error al escribir en Redis, continuando sin caché: ${redisError.message}`);
      }
    }

    if (this.eventPublisher && result.totalDeployments > 0) {
      const eventPayload = {
        event: 'METRICS_CALCULATED',
        appId: id_app,
        averageTime,
        totalDeployments: deployments.length,
        timestamp: new Date().toISOString()
      };

      this.eventPublisher.publish('metrics.calculated', eventPayload)
        .then(() => {
          logger.info(`[MetricsService] Evento METRICS_CALCULATED publicado para app ${id_app}`);
        })
        .catch((publishError) => {
          logger.error(`[MetricsService] Error al publicar evento en RabbitMQ: ${publishError.message}`);
        });
    }

    logger.info(`[MetricsService] Promedio calculado para app ${id_app}: ${averageTime}s sobre ${deployments.length} despliegues`);

    return result;
  }
}

module.exports = { MetricsService };

const bcrypt = require('bcrypt');
const userRepository = require('../repositories/user.repository');
const cacheClient = require('../cache/redis.client');
const eventPublisher = require('../events/event.publisher');
const logger = require('../utils/logger');
const config = require('../config');

const SALT_ROUNDS = 12;
const ALLOWED_ROLES = ['admin', 'user'];
const DEFAULT_ROLE = 'user';
const ALLOWED_UPDATE_FIELDS = ['name', 'role', 'status'];
const ALLOWED_CREATE_FIELDS = ['name', 'email', 'role', 'externalId', 'status'];

class ValidationError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ValidationError';
    this.statusCode = 400;
  }
}

function buildUserPayload(externalUser) {
  const payload = {};

  ALLOWED_CREATE_FIELDS.forEach((field) => {
    if (externalUser[field] !== undefined && externalUser[field] !== null) {
      payload[field] = externalUser[field];
    }
  });

  if (payload.role !== undefined) {
    const normalizedRole = String(payload.role).toLowerCase().trim();
    payload.role = ALLOWED_ROLES.includes(normalizedRole) ? normalizedRole : DEFAULT_ROLE;
  } else {
    payload.role = DEFAULT_ROLE;
  }

  return payload;
}

async function invalidateUserCache(userId) {
  try {
    const keysToDelete = [`user:${userId}`, 'users:list'];
    await Promise.all(keysToDelete.map((key) => cacheClient.del(key)));
    logger.debug({ userId }, 'Cache invalidated for user');
  } catch (cacheError) {
    logger.error({ err: cacheError, userId }, 'Failed to invalidate cache for user, continuing sync');
  }
}

async function publishUserEvent(eventType, userData) {
  try {
    const event = {
      type: eventType,
      payload: {
        id: userData.id,
        email: userData.email,
        role: userData.role,
        timestamp: new Date().toISOString(),
      },
    };

    const exchange = config.rabbitmq?.exchange || 'users.exchange';
    const queue = config.rabbitmq?.queue || 'users.sync';

    await eventPublisher.publish(exchange, queue, event);
    logger.debug({ eventType, userId: userData.id }, 'Event published to RabbitMQ');
  } catch (publishError) {
    logger.warn(
      { err: publishError, eventType, userId: userData.id },
      'Failed to publish event to RabbitMQ, continuing sync'
    );
  }
}

async function syncUsers(usersPayload) {
  if (!Array.isArray(usersPayload) || usersPayload.length === 0) {
    throw new ValidationError(
      'usersPayload must be a non-empty array of user objects'
    );
  }

  const summary = {
    total: usersPayload.length,
    created: 0,
    updated: 0,
    failed: [],
  };

  for (const externalUser of usersPayload) {
    const userIdentifier = externalUser.externalId || externalUser.email || 'unknown';

    try {
      const cleanPayload = buildUserPayload(externalUser);

      if (!cleanPayload.email) {
        throw new ValidationError(`User with identifier "${userIdentifier}" is missing required field: email`);
      }

      const existingUser = await userRepository.findByEmailOrExternalId(
        cleanPayload.email,
        cleanPayload.externalId
      );

      if (!existingUser) {
        if (!cleanPayload.password && !externalUser.password) {
          cleanPayload.password = await bcrypt.hash(
            Math.random().toString(36).slice(-12) + Date.now(),
            SALT_ROUNDS
          );
        } else if (externalUser.password) {
          cleanPayload.password = await bcrypt.hash(externalUser.password, SALT_ROUNDS);
        }

        const createdUser = await userRepository.create(cleanPayload);

        logger.info({ userId: createdUser.id, email: createdUser.email }, 'User created during sync');

        await invalidateUserCache(createdUser.id);
        await publishUserEvent('user.created', createdUser);

        summary.created += 1;
      } else {
        const updatePayload = {};
        ALLOWED_UPDATE_FIELDS.forEach((field) => {
          if (cleanPayload[field] !== undefined) {
            updatePayload[field] = cleanPayload[field];
          }
        });

        const updatedUser = await userRepository.update(existingUser.id, updatePayload);

        logger.info({ userId: updatedUser.id, email: updatedUser.email }, 'User updated during sync');

        await invalidateUserCache(updatedUser.id);
        await publishUserEvent('user.updated', updatedUser);

        summary.updated += 1;
      }
    } catch (userError) {
      logger.error(
        { err: userError, userIdentifier },
        'Failed to process user during sync'
      );

      summary.failed.push({
        identifier: userIdentifier,
        error: userError.message || 'Unknown error during user processing',
      });
    }
  }

  logger.info(
    {
      total: summary.total,
      created: summary.created,
      updated: summary.updated,
      failedCount: summary.failed.length,
    },
    'User sync completed'
  );

  return summary;
}

module.exports = {
  syncUsers,
};

'use strict';

/**
 * @fileoverview Base repository class providing generic CRUD operations for SQLite via better-sqlite3.
 * All concrete repositories must extend this class.
 */

/**
 * Validates that a field name contains only alphanumeric characters and underscores.
 * This prevents SQL injection via dynamic column names.
 * @param {string} fieldName - The field name to validate.
 * @returns {boolean} True if valid, false otherwise.
 */
const isValidFieldName = (fieldName) => /^[a-zA-Z_][a-zA-Z0-9_]*$/.test(fieldName);

/**
 * Abstract base repository class encapsulating generic SQLite data access operations.
 * Do NOT instantiate this class directly; extend it in concrete repository implementations.
 */
class BaseRepository {
  /**
   * Creates a BaseRepository instance.
   * NOTE: This is an abstract class and should not be instantiated directly.
   * Concrete repositories must extend this class and call super(db, tableName).
   *
   * @param {import('better-sqlite3').Database} db - The better-sqlite3 database connection instance.
   * @param {string} tableName - The name of the database table this repository operates on.
   * @throws {Error} If db or tableName are missing or of incorrect type.
   */
  constructor(db, tableName) {
    if (!db || typeof db !== 'object' || typeof db.prepare !== 'function') {
      throw new Error(
        'BaseRepository: Invalid or missing "db" parameter. Expected a better-sqlite3 Database instance.'
      );
    }

    if (!tableName || typeof tableName !== 'string' || tableName.trim() === '') {
      throw new Error(
        'BaseRepository: Invalid or missing "tableName" parameter. Expected a non-empty string.'
      );
    }

    if (!isValidFieldName(tableName)) {
      throw new Error(
        `BaseRepository: "tableName" contains invalid characters: "${tableName}". Only alphanumeric characters and underscores are allowed.`
      );
    }

    /** @private */
    this._db = db;

    /** @protected */
    this.tableName = tableName;
  }

  /**
   * Returns the database connection instance.
   * @protected
   * @returns {import('better-sqlite3').Database} The database connection.
   */
  get db() {
    return this._db;
  }

  /**
   * Retrieves all records from the table with optional pagination and ordering.
   *
   * @param {Object} [options={}] - Query options.
   * @param {number} [options.limit] - Maximum number of records to return.
   * @param {number} [options.offset] - Number of records to skip.
   * @param {string} [options.orderBy] - Column name to order results by.
   * @param {'ASC'|'DESC'} [options.orderDir='ASC'] - Order direction.
   * @returns {Array<Object>} Array of records, empty array if none found.
   * @throws {Error} If the database operation fails.
   */
  findAll(options = {}) {
    try {
      const { limit, offset, orderBy, orderDir = 'ASC' } = options;

      let query = `SELECT * FROM ${this.tableName}`;

      if (orderBy) {
        if (!isValidFieldName(orderBy)) {
          throw new Error(
            `findAll: Invalid "orderBy" field name: "${orderBy}". Only alphanumeric characters and underscores are allowed.`
          );
        }
        const direction = orderDir.toUpperCase() === 'DESC' ? 'DESC' : 'ASC';
        query += ` ORDER BY ${orderBy} ${direction}`;
      }

      if (typeof limit === 'number' && Number.isInteger(limit) && limit > 0) {
        query += ` LIMIT ${limit}`;
      }

      if (typeof offset === 'number' && Number.isInteger(offset) && offset >= 0) {
        query += ` OFFSET ${offset}`;
      }

      const stmt = this._db.prepare(query);
      const rows = stmt.all();

      return rows || [];
    } catch (error) {
      throw new Error(
        `BaseRepository [${this.tableName}] findAll failed: ${error.message}`
      );
    }
  }

  /**
   * Finds a single record by its primary key ID.
   *
   * @param {number|string} id - The primary key value to search for.
   * @returns {Object|null} The found record object, or null if not found.
   * @throws {Error} If the database operation fails.
   */
  findById(id) {
    try {
      const stmt = this._db.prepare(
        `SELECT * FROM ${this.tableName} WHERE id = ?`
      );
      const row = stmt.get(id);

      return row || null;
    } catch (error) {
      throw new Error(
        `BaseRepository [${this.tableName}] findById failed for id "${id}": ${error.message}`
      );
    }
  }

  /**
   * Finds all records matching a specific field-value condition.
   *
   * @param {string} field - The column name to filter by.
   * @param {*} value - The value to match against the field.
   * @returns {Array<Object>} Array of matching records, empty array if none found.
   * @throws {Error} If the field name is invalid or the database operation fails.
   */
  findBy(field, value) {
    try {
      if (!field || typeof field !== 'string' || field.trim() === '') {
        throw new Error(
          `findBy: "field" parameter must be a non-empty string. Received: "${field}".`
        );
      }

      if (!isValidFieldName(field)) {
        throw new Error(
          `findBy: Invalid "field" name: "${field}". Only alphanumeric characters and underscores are allowed.`
        );
      }

      const stmt = this._db.prepare(
        `SELECT * FROM ${this.tableName} WHERE ${field} = ?`
      );
      const rows = stmt.all(value);

      return rows || [];
    } catch (error) {
      throw new Error(
        `BaseRepository [${this.tableName}] findBy failed for field "${field}": ${error.message}`
      );
    }
  }

  /**
   * Inserts a new record into the table.
   *
   * @param {Object} data - Plain object containing the fields and values to insert.
   * @returns {Object} The newly created record retrieved by its inserted row ID.
   * @throws {Error} If data is empty, invalid, or the database operation fails.
   */
  create(data) {
    try {
      if (!data || typeof data !== 'object' || Array.isArray(data)) {
        throw new Error(
          'create: "data" parameter must be a non-null plain object.'
        );
      }

      const keys = Object.keys(data);

      if (keys.length === 0) {
        throw new Error(
          'create: "data" object must contain at least one field to insert.'
        );
      }

      for (const key of keys) {
        if (!isValidFieldName(key)) {
          throw new Error(
            `create: Invalid field name "${key}" in data object. Only alphanumeric characters and underscores are allowed.`
          );
        }
      }

      const columns = keys.join(', ');
      const placeholders = keys.map(() => '?').join(', ');
      const values = keys.map((key) => data[key]);

      const stmt = this._db.prepare(
        `INSERT INTO ${this.tableName} (${columns}) VALUES (${placeholders})`
      );

      const result = stmt.run(...values);

      return this.findById(result.lastInsertRowid);
    } catch (error) {
      throw new Error(
        `BaseRepository [${this.tableName}] create failed: ${error.message}`
      );
    }
  }

  /**
   * Updates an existing record by its primary key ID.
   *
   * @param {number|string} id - The primary key of the record to update.
   * @param {Object} data - Plain object containing the fields and new values to set.
   * @returns {Object|null} The updated record object, or null if not found.
   * @throws {Error} If data is empty, contains invalid fields, or the database operation fails.
   */
  update(id, data) {
    try {
      if (!data || typeof data !== 'object' || Array.isArray(data)) {
        throw new Error(
          'update: "data" parameter must be a non-null plain object.'
        );
      }

      const filteredData = Object.keys(data)
        .filter((key) => key !== 'id')
        .reduce((acc, key) => {
          acc[key] = data[key];
          return acc;
        }, {});

      const keys = Object.keys(filteredData);

      if (keys.length === 0) {
        throw new Error(
          'update: No valid fields to update. "data" object is empty or contains only the "id" field.'
        );
      }

      for (const key of keys) {
        if (!isValidFieldName(key)) {
          throw new Error(
            `update: Invalid field name "${key}" in data object. Only alphanumeric characters and underscores are allowed.`
          );
        }
      }

      const setClause = keys.map((key) => `${key} = ?`).join(', ');
      const values = keys.map((key) => filteredData[key]);

      const stmt = this._db.prepare(
        `UPDATE ${this.tableName} SET ${setClause} WHERE id = ?`
      );

      stmt.run(...values, id);

      return this.findById(id);
    } catch (error) {
      throw new Error(
        `BaseRepository [${this.tableName}] update failed for id "${id}": ${error.message}`
      );
    }
  }

  /**
   * Deletes a record from the table by its primary key ID.
   *
   * @param {number|string} id - The primary key of the record to delete.
   * @returns {boolean} True if at least one row was deleted, false otherwise.
   * @throws {Error} If the database operation fails.
   */
  delete(id) {
    try {
      const stmt = this._db.prepare(
        `DELETE FROM ${this.tableName} WHERE id = ?`
      );

      const result = stmt.run(id);

      return result.changes > 0;
    } catch (error) {
      throw new Error(
        `BaseRepository [${this.tableName}] delete failed for id "${id}": ${error.message}`
      );
    }
  }

  /**
   * Counts the total number of records in the table, optionally filtered by conditions.
   *
   * @param {Object} [whereClause={}] - Optional key-value pairs representing WHERE conditions.
   * @returns {number} The count of matching records.
   * @throws {Error} If field names are invalid or the database operation fails.
   */
  count(whereClause = {}) {
    try {
      if (typeof whereClause !== 'object' || Array.isArray(whereClause)) {
        throw new Error(
          'count: "whereClause" parameter must be a plain object.'
        );
      }

      const keys = Object.keys(whereClause);
      let query = `SELECT COUNT(*) AS total FROM ${this.tableName}`;
      let values = [];

      if (keys.length > 0) {
        for (const key of keys) {
          if (!isValidFieldName(key)) {
            throw new Error(
              `count: Invalid field name "${key}" in whereClause. Only alphanumeric characters and underscores are allowed.`
            );
          }
        }

        const conditions = keys.map((key) => `${key} = ?`).join(' AND ');
        values = keys.map((key) => whereClause[key]);
        query += ` WHERE ${conditions}`;
      }

      const stmt = this._db.prepare(query);
      const row = stmt.get(...values);

      return row ? row.total : 0;
    } catch (error) {
      throw new Error(
        `BaseRepository [${this.tableName}] count failed: ${error.message}`
      );
    }
  }
}

module.exports = BaseRepository;

const db = require('../config/database');

class UsersRepository {
  constructor(database) {
    this.db = database;

    this._findAllStmt = this.db.prepare(
      `SELECT id, username, email, role, created_at, updated_at FROM users`
    );

    this._findByIdStmt = this.db.prepare(
      `SELECT id, username, email, role, created_at, updated_at FROM users WHERE id = ?`
    );

    this._findByEmailStmt = this.db.prepare(
      `SELECT id, username, email, password, role, created_at, updated_at FROM users WHERE email = ?`
    );

    this._findByUsernameStmt = this.db.prepare(
      `SELECT id, username, email, password, role, created_at, updated_at FROM users WHERE username = ?`
    );

    this._createStmt = this.db.prepare(
      `INSERT INTO users (username, email, password, role, created_at, updated_at)
       VALUES (?, ?, ?, ?, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)`
    );

    this._removeStmt = this.db.prepare(
      `DELETE FROM users WHERE id = ?`
    );

    this._existsByEmailStmt = this.db.prepare(
      `SELECT COUNT(*) as count FROM users WHERE email = ? AND id != ?`
    );

    this._existsByEmailNoExcludeStmt = this.db.prepare(
      `SELECT COUNT(*) as count FROM users WHERE email = ?`
    );

    this._existsByUsernameStmt = this.db.prepare(
      `SELECT COUNT(*) as count FROM users WHERE username = ? AND id != ?`
    );

    this._existsByUsernameNoExcludeStmt = this.db.prepare(
      `SELECT COUNT(*) as count FROM users WHERE username = ?`
    );
  }

  findAll() {
    const rows = this._findAllStmt.all();
    return rows || [];
  }

  findById(id) {
    const row = this._findByIdStmt.get(id);
    return row || null;
  }

  findByEmail(email) {
    const row = this._findByEmailStmt.get(email);
    return row || null;
  }

  findByUsername(username) {
    const row = this._findByUsernameStmt.get(username);
    return row || null;
  }

  create({ username, email, password, role }) {
    const result = this._createStmt.run(username, email, password, role);
    return this.findById(result.lastInsertRowid);
  }

  update(id, data) {
    const forbiddenKeys = ['id', 'created_at'];
    const allowedData = Object.keys(data)
      .filter((key) => !forbiddenKeys.includes(key))
      .reduce((acc, key) => {
        acc[key] = data[key];
        return acc;
      }, {});

    const keys = Object.keys(allowedData);

    if (keys.length === 0) {
      return this.findById(id);
    }

    const setClauses = keys.map((key) => `${key} = ?`);
    setClauses.push('updated_at = CURRENT_TIMESTAMP');

    const values = keys.map((key) => allowedData[key]);
    values.push(id);

    const query = `UPDATE users SET ${setClauses.join(', ')} WHERE id = ?`;
    const stmt = this.db.prepare(query);
    stmt.run(...values);

    return this.findById(id);
  }

  remove(id) {
    const result = this._removeStmt.run(id);
    return result.changes > 0;
  }

  existsByEmail(email, excludeId = null) {
    if (excludeId !== null) {
      const row = this._existsByEmailStmt.get(email, excludeId);
      return row.count > 0;
    }
    const row = this._existsByEmailNoExcludeStmt.get(email);
    return row.count > 0;
  }

  existsByUsername(username, excludeId = null) {
    if (excludeId !== null) {
      const row = this._existsByUsernameStmt.get(username, excludeId);
      return row.count > 0;
    }
    const row = this._existsByUsernameNoExcludeStmt.get(username);
    return row.count > 0;
  }
}

module.exports = new UsersRepository(db);
module.exports.UsersRepository = UsersRepository;

const db = require('../config/database');

class DeploymentRepository {
  initialize() {
    try {
      db.exec(`
        CREATE TABLE IF NOT EXISTS deployments (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          id_app TEXT NOT NULL,
          status TEXT NOT NULL DEFAULT 'IN_PROGRESS',
          deployed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
          duration_seconds REAL,
          deployed_by INTEGER,
          metadata TEXT,
          created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
        )
      `);
    } catch (error) {
      throw new Error(`DeploymentRepository.initialize: ${error.message}`);
    }
  }

  /**
   * Crea un nuevo registro de despliegue en la base de datos.
   * @param {Object} deploymentData - Datos del despliegue a registrar.
   * @param {string} deploymentData.id_app - Identificador de la aplicación desplegada.
   * @param {string} deploymentData.status - Estado del despliegue (SUCCESS, FAILED, IN_PROGRESS).
   * @param {string} deploymentData.deployed_at - Timestamp ISO 8601 del despliegue.
   * @param {number} [deploymentData.duration_seconds] - Duración del despliegue en segundos.
   * @param {number|string} [deploymentData.deployed_by] - Referencia al usuario que ejecutó el despliegue.
   * @param {string} [deploymentData.metadata] - JSON serializado con información adicional.
   * @returns {Object} El objeto del despliegue recién creado incluyendo el id generado.
   */
  create(deploymentData) {
    try {
      const { id_app, status, deployed_at, duration_seconds, deployed_by, metadata } = deploymentData;

      const stmt = db.prepare(`
        INSERT INTO deployments (id_app, status, deployed_at, duration_seconds, deployed_by, metadata)
        VALUES (?, ?, ?, ?, ?, ?)
      `);

      const result = stmt.run(
        id_app,
        status,
        deployed_at || new Date().toISOString(),
        duration_seconds !== undefined ? duration_seconds : null,
        deployed_by !== undefined ? deployed_by : null,
        metadata !== undefined ? metadata : null
      );

      return this.findById(result.lastInsertRowid);
    } catch (error) {
      throw new Error(`DeploymentRepository.create: ${error.message}`);
    }
  }

  /**
   * Busca un despliegue por su ID.
   * @param {number|string} id - ID del despliegue.
   * @returns {Object|null} El objeto del despliegue o null si no existe.
   */
  findById(id) {
    try {
      const stmt = db.prepare('SELECT * FROM deployments WHERE id = ?');
      const row = stmt.get(id);
      return row || null;
    } catch (error) {
      throw new Error(`DeploymentRepository.findById: ${error.message}`);
    }
  }

  /**
   * Retorna una lista de despliegues aplicando filtros opcionales.
   * @param {Object} [filters={}] - Filtros opcionales.
   * @param {string} [filters.id_app] - Filtrar por identificador de aplicación.
   * @param {string} [filters.status] - Filtrar por estado del despliegue.
   * @param {number} [filters.limit=100] - Límite de registros a retornar.
   * @param {number} [filters.offset=0] - Desplazamiento para paginación.
   * @returns {Object[]} Array de objetos de despliegue.
   */
  findAll(filters = {}) {
    try {
      const conditions = [];
      const params = [];

      if (filters.id_app !== undefined && filters.id_app !== null) {
        conditions.push('id_app = ?');
        params.push(filters.id_app);
      }

      if (filters.status !== undefined && filters.status !== null) {
        conditions.push('status = ?');
        params.push(filters.status);
      }

      let query = 'SELECT * FROM deployments';

      if (conditions.length > 0) {
        query += ' WHERE ' + conditions.join(' AND ');
      }

      query += ' ORDER BY created_at DESC';

      const limit = filters.limit !== undefined ? parseInt(filters.limit, 10) : 100;
      const offset = filters.offset !== undefined ? parseInt(filters.offset, 10) : 0;

      query += ' LIMIT ? OFFSET ?';
      params.push(limit, offset);

      const stmt = db.prepare(query);
      const rows = stmt.all(...params);
      return rows || [];
    } catch (error) {
      throw new Error(`DeploymentRepository.findAll: ${error.message}`);
    }
  }

  /**
   * Calcula el tiempo promedio de despliegue exitoso para una aplicación en un rango de días.
   * @param {string|number} id_app - Identificador de la aplicación.
   * @param {number} [days=7] - Número de días hacia atrás a considerar.
   * @returns {number|null} Promedio en segundos o null si no hay registros.
   */
  getAverageDeploymentTime(id_app, days = 7) {
    try {
      const stmt = db.prepare(`
        SELECT AVG(duration_seconds) AS average_time
        FROM deployments
        WHERE id_app = ?
          AND status = 'SUCCESS'
          AND deployed_at >= datetime('now', ? )
      `);

      const row = stmt.get(id_app, `-${days} days`);

      if (!row || row.average_time === null || row.average_time === undefined) {
        return null;
      }

      return parseFloat(row.average_time);
    } catch (error) {
      throw new Error(`DeploymentRepository.getAverageDeploymentTime: ${error.message}`);
    }
  }

  /**
   * Actualiza los campos de un despliegue existente.
   * @param {number|string} id - ID del despliegue a actualizar.
   * @param {Object} updateData - Campos a actualizar.
   * @returns {Object|null} El objeto actualizado completo o null si no existe.
   */
  update(id, updateData) {
    try {
      const forbiddenFields = ['id', 'created_at'];
      const fields = Object.keys(updateData).filter(key => !forbiddenFields.includes(key));

      if (fields.length === 0) {
        return this.findById(id);
      }

      const setClauses = fields.map(field => `${field} = ?`);
      const params = fields.map(field => updateData[field]);
      params.push(id);

      const query = `UPDATE deployments SET ${setClauses.join(', ')} WHERE id = ?`;
      const stmt = db.prepare(query);
      const result = stmt.run(...params);

      if (result.changes === 0) {
        return null;
      }

      return this.findById(id);
    } catch (error) {
      throw new Error(`DeploymentRepository.update: ${error.message}`);
    }
  }

  /**
   * Elimina un despliegue por su ID.
   * @param {number|string} id - ID del despliegue a eliminar.
   * @returns {boolean} true si se eliminó al menos una fila, false en caso contrario.
   */
  delete(id) {
    try {
      const stmt = db.prepare('DELETE FROM deployments WHERE id = ?');
      const result = stmt.run(id);
      return result.changes > 0;
    } catch (error) {
      throw new Error(`DeploymentRepository.delete: ${error.message}`);
    }
  }
}

module.exports = new DeploymentRepository();

const jwt = require('jsonwebtoken');
const process = require('process');

const verifyToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({
      success: false,
      message: 'No se proporcionó token de autenticación o el formato es inválido. Use: Bearer <token>',
    });
  }

  const token = authHeader.split(' ')[1];

  if (!token || token.trim() === '') {
    return res.status(401).json({
      success: false,
      message: 'No se proporcionó token de autenticación o el formato es inválido. Use: Bearer <token>',
    });
  }

  const secret = process.env.JWT_SECRET;

  if (!secret) {
    return res.status(500).json({
      success: false,
      message: 'Error de configuración del servidor. Contacte al administrador.',
    });
  }

  try {
    const decoded = jwt.verify(token, secret);

    req.user = {
      id: decoded.id,
      email: decoded.email,
      role: decoded.role,
    };

    return next();
  } catch (error) {
    if (error.name === 'TokenExpiredError') {
      return res.status(401).json({
        success: false,
        message: 'El token de autenticación ha expirado. Por favor, inicie sesión nuevamente.',
      });
    }

    return res.status(401).json({
      success: false,
      message: 'El token de autenticación es inválido.',
    });
  }
};

const requireRole = (...allowedRoles) => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({
        success: false,
        message: 'Autenticación requerida. Por favor, inicie sesión.',
      });
    }

    const userRole = req.user.role;

    if (!allowedRoles.includes(userRole)) {
      return res.status(403).json({
        success: false,
        message: 'No tiene permisos suficientes para acceder a este recurso.',
      });
    }

    return next();
  };
};

module.exports = { verifyToken, requireRole };

/**
 * @module rbac.middleware
 * @description Middleware de autorización basado en roles (RBAC).
 * Se ejecuta después del middleware de autenticación JWT y verifica
 * que el usuario autenticado posee el rol requerido para acceder al recurso.
 */

/**
 * Función de orden superior que genera un middleware Express de autorización RBAC.
 *
 * @param {...string} roles - Uno o más roles permitidos para acceder al recurso.
 * @returns {Function} Middleware Express con firma (req, res, next).
 * @example
 * router.get('/users', authenticateJWT, authorizeRoles('admin'), userController.list);
 */
const authorizeRoles = (...roles) => {
  // Validación en tiempo de configuración: se debe especificar al menos un rol
  if (!roles || roles.length === 0) {
    throw new Error('authorizeRoles: Se debe especificar al menos un rol permitido.');
  }

  return (req, res, next) => {
    try {
      // Paso 1 - Verificar existencia de usuario autenticado
      if (!req.user) {
        return res.status(401).json({
          status: 'error',
          message: 'No hay sesión autenticada. Acceso denegado.'
        });
      }

      // Paso 2 - Verificar existencia del campo rol en el usuario autenticado
      if (!req.user.role) {
        return res.status(403).json({
          status: 'error',
          message: 'El usuario no tiene rol asignado. Acceso denegado.'
        });
      }

      // Paso 3 - Verificar si el rol del usuario está en la lista de roles permitidos
      if (!roles.includes(req.user.role)) {
        return res.status(403).json({
          status: 'error',
          message: 'Acceso denegado por rol insuficiente.',
          required: roles,
          current: req.user.role
        });
      }

      // Paso 4 - Autorización exitosa, continuar al siguiente middleware o controlador
      next();
    } catch (error) {
      // Delegar cualquier error inesperado al manejador de errores global de Express
      next(error);
    }
  };
};

module.exports = { authorizeRoles };

const Joi = require('joi');

const validate = (schema) => {
  return (req, res, next) => {
    try {
      const isBodyMethod = req.method === 'POST' || req.method === 'PUT';
      const data = isBodyMethod
        ? req.body
        : Object.assign({}, req.params, req.query);

      const { error, value } = schema.validate(data, {
        abortEarly: false,
        stripUnknown: true,
      });

      if (error) {
        const errors = error.details.map((detail) => ({
          field: detail.path.join('.'),
          message: detail.message.replace(/"/g, ''),
        }));

        return res.status(422).json({
          status: 'error',
          message: 'Validation failed',
          errors: errors,
        });
      }

      if (isBodyMethod) {
        req.body = value;
      } else {
        req.params = value;
      }

      return next();
    } catch (err) {
      return next(err);
    }
  };
};

module.exports = validate;

const rateLimit = require('express-rate-limit');

/**
 * @module rateLimiter.middleware
 * @description Middleware de limitación de tasa de peticiones HTTP para proteger la API
 * contra ataques de fuerza bruta, DDoS y abuso de endpoints.
 *
 * Exporta tres instancias diferenciadas:
 * - authLimiter: Para el endpoint de autenticación POST /api/v1/auth/login
 * - generalLimiter: Para todos los endpoints de la API como capa base de protección
 * - syncLimiter: Para el endpoint costoso POST /api/v1/sync/users
 *
 * @prerequisite El archivo principal app.js debe tener configurado `app.set('trust proxy', 1)`
 * para que req.ip resuelva correctamente la IP real del cliente cuando la aplicación
 * corre detrás de un reverse proxy (Nginx, Kubernetes Ingress, etc.).
 *
 * TODO: En entornos multi-instancia (múltiples pods/contenedores), reemplazar el store
 * en memoria por `rate-limit-redis` usando la instancia de Redis ya configurada en
 * src/config/redis.js para compartir contadores entre instancias y garantizar
 * consistencia del rate limiting distribuido.
 */

// ─── Constantes de configuración ────────────────────────────────────────────
// Los valores son configuración de seguridad fija definida por el equipo,
// no se leen desde variables de entorno para garantizar consistencia.

const AUTH_WINDOW_MS = 15 * 60 * 1000; // 15 minutos en milisegundos
const AUTH_MAX_REQUESTS = 10;

const GENERAL_WINDOW_MS = 1 * 60 * 1000; // 1 minuto en milisegundos
const GENERAL_MAX_REQUESTS = 100;

const SYNC_WINDOW_MS = 60 * 60 * 1000; // 1 hora en milisegundos
const SYNC_MAX_REQUESTS = 5;

// ─── authLimiter ─────────────────────────────────────────────────────────────
// Destinado exclusivamente al endpoint POST /api/v1/auth/login
const authLimiter = rateLimit({
  windowMs: AUTH_WINDOW_MS,
  max: AUTH_MAX_REQUESTS,

  // skipFailedRequests: false — Los intentos fallidos de login también cuentan
  // contra el límite. Esto es crítico para prevenir ataques de fuerza bruta:
  // si solo se contaran los exitosos, un atacante podría hacer intentos ilimitados
  // de credenciales incorrectas sin ser bloqueado.
  skipFailedRequests: false,

  standardHeaders: true,
  legacyHeaders: false,

  keyGenerator: (req) => req.ip,

  handler: (req, res, next, options) => {
    res.status(429).json({
      status: 429,
      error: 'Has superado el límite de intentos de autenticación. Por favor, inténtalo de nuevo más tarde.',
      retryAfter: 'Reintenta después de 15 minutos.',
    });
  },
});

// ─── generalLimiter ──────────────────────────────────────────────────────────
// Destinado a todos los endpoints de la API como capa base de protección global
const generalLimiter = rateLimit({
  windowMs: GENERAL_WINDOW_MS,
  max: GENERAL_MAX_REQUESTS,

  standardHeaders: true,
  legacyHeaders: false,

  keyGenerator: (req) => req.ip,

  handler: (req, res, next, options) => {
    res.status(429).json({
      status: 429,
      error: 'Demasiadas peticiones realizadas desde esta IP. Por favor, reduce la frecuencia de tus solicitudes.',
      retryAfter: 'Reintenta en 1 minuto.',
    });
  },
});

// ─── syncLimiter ─────────────────────────────────────────────────────────────
// Destinado al endpoint POST /api/v1/sync/users, operación costosa en recursos
const syncLimiter = rateLimit({
  windowMs: SYNC_WINDOW_MS,
  max: SYNC_MAX_REQUESTS,

  standardHeaders: true,
  legacyHeaders: false,

  keyGenerator: (req) => req.ip,

  handler: (req, res, next, options) => {
    res.status(429).json({
      status: 429,
      error: 'Has alcanzado el límite de sincronizaciones permitidas. Por favor, espera antes de volver a sincronizar.',
      retryAfter: 'Reintenta en 1 hora.',
    });
  },
});

module.exports = {
  authLimiter,
  generalLimiter,
  syncLimiter,
};

const AppError = class AppError extends Error {
  constructor(message, statusCode, isOperational = true) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = isOperational;
    this.name = this.constructor.name;
    Error.captureStackTrace(this, this.constructor);
  }
};

const deriveErrorCode = (statusCode, err) => {
  if (err.errorCode) return err.errorCode;
  if (err.code) return err.code;
  const codeMap = {
    400: 'VALIDATION_ERROR',
    401: 'UNAUTHORIZED',
    403: 'FORBIDDEN',
    404: 'NOT_FOUND',
    409: 'CONFLICT',
    422: 'UNPROCESSABLE_ENTITY',
    429: 'TOO_MANY_REQUESTS',
    500: 'INTERNAL_ERROR',
  };
  return codeMap[statusCode] || 'INTERNAL_ERROR';
};

const normalizeError = (err) => {
  if (err instanceof AppError) {
    return err;
  }

  if (err.name === 'JsonWebTokenError') {
    const normalized = new AppError('Invalid token', 401, true);
    normalized.errorCode = 'INVALID_TOKEN';
    return normalized;
  }

  if (err.name === 'TokenExpiredError') {
    const normalized = new AppError('Token expired', 401, true);
    normalized.errorCode = 'TOKEN_EXPIRED';
    return normalized;
  }

  if (err.isJoi === true || (err.name === 'ValidationError' && err.details)) {
    const normalized = new AppError(err.message, 400, true);
    normalized.errorCode = 'VALIDATION_ERROR';
    return normalized;
  }

  if (err.code === 'SQLITE_CONSTRAINT') {
    const normalized = new AppError('Resource already exists', 409, true);
    normalized.errorCode = 'CONFLICT';
    return normalized;
  }

  if (err.code === 'SQLITE_NOTFOUND') {
    const normalized = new AppError('Resource not found', 404, true);
    normalized.errorCode = 'NOT_FOUND';
    return normalized;
  }

  const normalized = new AppError(
    err.message || 'Internal server error',
    err.statusCode || err.status || 500,
    false
  );
  normalized.originalStack = err.stack;
  return normalized;
};

const errorHandler = (err, req, res, next) => {
  const nodeEnv = process.env.NODE_ENV || 'development';
  const normalizedError = normalizeError(err);

  const { statusCode, isOperational, message, stack } = normalizedError;

  if (nodeEnv === 'development') {
    console.error('[ErrorHandler] Error:', {
      message,
      statusCode,
      isOperational,
      path: req.path,
      method: req.method,
      stack: stack || normalizedError.originalStack || err.stack,
    });
  } else {
    if (!isOperational) {
      console.error('[ErrorHandler] CRITICAL - Unexpected error:', {
        message,
        statusCode,
        path: req.path,
        method: req.method,
        stack: stack || normalizedError.originalStack || err.stack,
        timestamp: new Date().toISOString(),
      });
    }
  }

  const isProduction = nodeEnv === 'production';
  const safeMessage = isProduction && !isOperational ? 'Internal server error' : message;
  const errorCode = deriveErrorCode(statusCode, normalizedError);

  const responseBody = {
    status: 'error',
    statusCode,
    message: safeMessage,
    errorCode,
    timestamp: new Date().toISOString(),
    path: req.path,
  };

  if (nodeEnv === 'development') {
    responseBody.stack = stack || normalizedError.originalStack || err.stack;
  }

  res.status(statusCode).json(responseBody);
};

module.exports = errorHandler;
module.exports.AppError = AppError;

const crypto = require('crypto');

function sanitizeUrl(url) {
  try {
    const sensitiveParams = ['password', 'token', 'secret', 'apikey'];
    const [path, queryString] = url.split('?');

    if (!queryString) {
      return url;
    }

    const sanitizedParams = queryString
      .split('&')
      .map((param) => {
        const [key, value] = param.split('=');
        const lowerKey = key ? key.toLowerCase() : '';
        if (sensitiveParams.includes(lowerKey)) {
          return `${key}=[REDACTED]`;
        }
        return param;
      })
      .join('&');

    return `${path}?${sanitizedParams}`;
  } catch (e) {
    return url;
  }
}

function loggerMiddleware(req, res, next) {
  if (req.originalUrl === '/api/health') {
    return next();
  }

  const correlationId = crypto.randomUUID();
  req.correlationId = correlationId;
  res.setHeader('X-Correlation-Id', correlationId);

  const startTime = Date.now();

  res.on('finish', () => {
    const responseTimeMs = Date.now() - startTime;
    const statusCode = res.statusCode;

    let level;
    if (statusCode >= 500) {
      level = 'ERROR';
    } else if (statusCode >= 400) {
      level = 'WARN';
    } else {
      level = 'INFO';
    }

    const logEntry = {
      timestamp: new Date().toISOString(),
      level,
      correlationId,
      method: req.method,
      url: sanitizeUrl(req.originalUrl),
      statusCode,
      responseTimeMs,
      ip: req.ip || (req.connection && req.connection.remoteAddress) || '',
      userAgent: req.headers['user-agent'] || '',
      userId: req.user ? req.user.id : null,
    };

    const serialized = JSON.stringify(logEntry);

    if (level === 'ERROR') {
      console.error(serialized);
    } else if (level === 'WARN') {
      console.warn(serialized);
    } else {
      console.log(serialized);
    }
  });

  next();
}

module.exports = loggerMiddleware;

