const validateDeployment = (req, res, next) => {
  const { error, value } = deploymentSchema.validate(req.body, {
    abortEarly: false,
    allowUnknown: false,
    stripUnknown: false,
  });

  if (error) {
    const errors = error.details.map((detail) => ({
      field: detail.context && detail.context.key ? detail.context.key : 'unknown',
      message: detail.message.replace(/"/g, ''),
    }));

    return res.status(422).json({
      status: 'error',
      message: 'Validation failed',
      errors,
    });
  }

  req.body = value;
  return next();
};

module.exports = {
  deploymentSchema,
  validateDeployment,
};

const Joi = require('joi');

const loginSchema = Joi.object({
  email: Joi.string()
    .lowercase()
    .trim()
    .max(254)
    .email()
    .required()
    .messages({
      'any.required': 'El email es requerido',
      'string.empty': 'El email es requerido',
      'string.email': 'Debe ser un email válido',
      'string.max': 'El email no debe superar los 254 caracteres',
    }),

  password: Joi.string()
    .min(8)
    .max(128)
    .required()
    .messages({
      'any.required': 'La contraseña es requerida',
      'string.empty': 'La contraseña es requerida',
      'string.min': 'La contraseña debe tener al menos 8 caracteres',
      'string.max': 'La contraseña no debe superar los 128 caracteres',
    }),
}).options({
  abortEarly: false,
  allowUnknown: false,
  stripUnknown: false,
});

const validateLogin = (req, res, next) => {
  const { error, value } = loginSchema.validate(req.body);

  if (error) {
    const errors = error.details.map((detail) => detail.message);

    return res.status(400).json({
      status: 'error',
      message: 'Datos de entrada inválidos',
      errors,
    });
  }

  req.body = value;
  next();
};

module.exports = {
  loginSchema,
  validateLogin,
};

const VALID_STATUSES = ['SUCCESS', 'FAILED', 'IN_PROGRESS'];

function _parseMetadata(record) {
  if (!record) return record;
  if (record.metadata === null || record.metadata === undefined) {
    return { ...record, metadata: null };
  }
  try {
    return { ...record, metadata: JSON.parse(record.metadata) };
  } catch {
    return { ...record, metadata: null };
  }
}

class DeploymentModel {
  constructor(db) {
    this.db = db;
  }

  initialize() {
    try {
      this.db.exec(`
        CREATE TABLE IF NOT EXISTS deployments (
          id               INTEGER PRIMARY KEY AUTOINCREMENT,
          id_app           TEXT    NOT NULL,
          status           TEXT    NOT NULL CHECK(status IN ('SUCCESS', 'FAILED', 'IN_PROGRESS')),
          deployed_at      TEXT    NOT NULL,
          duration_seconds INTEGER,
          deployed_by      TEXT    NOT NULL,
          metadata         TEXT,
          created_at       TEXT    NOT NULL DEFAULT (datetime('now'))
        )
      `);
    } catch (err) {
      throw new Error(`DeploymentModel.initialize: ${err.message}`);
    }
  }

  create(deploymentData) {
    try {
      const { id_app, status, deployed_at, duration_seconds, deployed_by, metadata } = deploymentData;

      const serializedMetadata =
        metadata !== null && metadata !== undefined
          ? typeof metadata === 'object'
            ? JSON.stringify(metadata)
            : metadata
          : null;

      const stmt = this.db.prepare(`
        INSERT INTO deployments (id_app, status, deployed_at, duration_seconds, deployed_by, metadata)
        VALUES (@id_app, @status, @deployed_at, @duration_seconds, @deployed_by, @metadata)
      `);

      const result = stmt.run({
        id_app,
        status,
        deployed_at,
        duration_seconds: duration_seconds !== undefined ? duration_seconds : null,
        deployed_by,
        metadata: serializedMetadata,
      });

      return this.findById(result.lastInsertRowid);
    } catch (err) {
      throw new Error(`DeploymentModel.create: ${err.message}`);
    }
  }

  findById(id) {
    try {
      const stmt = this.db.prepare('SELECT * FROM deployments WHERE id = ?');
      const record = stmt.get(id);
      if (!record) return null;
      return _parseMetadata(record);
    } catch (err) {
      throw new Error(`DeploymentModel.findById: ${err.message}`);
    }
  }

  findByAppId(id_app) {
    try {
      const stmt = this.db.prepare(
        'SELECT * FROM deployments WHERE id_app = ? ORDER BY deployed_at DESC'
      );
      const records = stmt.all(id_app);
      return records.map(_parseMetadata);
    } catch (err) {
      throw new Error(`DeploymentModel.findByAppId: ${err.message}`);
    }
  }

  findAverageTimeByAppId(id_app, days = 7) {
    try {
      const stmt = this.db.prepare(`
        SELECT
          AVG(duration_seconds) AS average_seconds,
          COUNT(*)              AS total_deployments
        FROM deployments
        WHERE id_app = ?
          AND status = 'SUCCESS'
          AND deployed_at >= datetime('now', ? || ' days')
      `);

      const row = stmt.get(id_app, `-${days}`);

      return {
        id_app,
        average_seconds: row.average_seconds !== null ? row.average_seconds : null,
        total_deployments: row.total_deployments,
      };
    } catch (err) {
      throw new Error(`DeploymentModel.findAverageTimeByAppId: ${err.message}`);
    }
  }

  findAll(filters = {}) {
    try {
      const conditions = [];
      const params = [];

      if (filters.id_app !== undefined && filters.id_app !== null) {
        conditions.push('id_app = ?');
        params.push(filters.id_app);
      }

      if (filters.status !== undefined && filters.status !== null) {
        conditions.push('status = ?');
        params.push(filters.status);
      }

      const whereClause = conditions.length > 0 ? `WHERE ${conditions.join(' AND ')}` : '';
      const sql = `SELECT * FROM deployments ${whereClause} ORDER BY created_at DESC`;

      const stmt = this.db.prepare(sql);
      const records = stmt.all(...params);
      return records.map(_parseMetadata);
    } catch (err) {
      throw new Error(`DeploymentModel.findAll: ${err.message}`);
    }
  }

  updateStatus(id, status, duration_seconds) {
    try {
      if (!VALID_STATUSES.includes(status)) {
        throw new Error(
          `Invalid status value '${status}'. Must be one of: ${VALID_STATUSES.join(', ')}`
        );
      }

      let sql;
      let params;

      if (duration_seconds !== undefined && duration_seconds !== null) {
        sql = 'UPDATE deployments SET status = ?, duration_seconds = ? WHERE id = ?';
        params = [status, duration_seconds, id];
      } else {
        sql = 'UPDATE deployments SET status = ? WHERE id = ?';
        params = [status, id];
      }

      const stmt = this.db.prepare(sql);
      const result = stmt.run(...params);

      if (result.changes === 0) return null;
      return this.findById(id);
    } catch (err) {
      throw new Error(`DeploymentModel.updateStatus: ${err.message}`);
    }
  }

  deleteById(id) {
    try {
      const stmt = this.db.prepare('DELETE FROM deployments WHERE id = ?');
      const result = stmt.run(id);
      return result.changes > 0;
    } catch (err) {
      throw new Error(`DeploymentModel.deleteById: ${err.message}`);
    }
  }
}

module.exports = DeploymentModel;

const amqplib = require('amqplib');

let connection = null;
let channel = null;

async function connect() {
  if (connection && channel) {
    return;
  }

  try {
    const url = process.env.RABBITMQ_URL || 'amqp://localhost';

    connection = await amqplib.connect(url);

    connection.on('error', (err) => {
      console.error('[RabbitMQ] Connection error:', err);
      connection = null;
      channel = null;
    });

    connection.on('close', () => {
      console.error('[RabbitMQ] Connection closed unexpectedly');
      connection = null;
      channel = null;
    });

    channel = await connection.createChannel();
  } catch (err) {
    console.error('[RabbitMQ] Failed to connect to RabbitMQ:', err);
    throw err;
  }
}

async function publishEvent(exchange, routingKey, payload) {
  try {
    await connect();

    await channel.assertExchange(exchange, 'topic', { durable: true });

    const buffer = Buffer.from(JSON.stringify(payload));

    channel.publish(exchange, routingKey, buffer, {
      persistent: true,
      contentType: 'application/json',
    });

    console.log(`[RabbitMQ] Event published - exchange: ${exchange}, routingKey: ${routingKey}`);
  } catch (err) {
    console.error(`[RabbitMQ] Failed to publish event - exchange: ${exchange}, routingKey: ${routingKey}`, err);
    throw err;
  }
}

async function closeConnection() {
  try {
    if (channel) {
      await channel.close();
    }
    if (connection) {
      await connection.close();
    }
  } catch (err) {
    console.error('[RabbitMQ] Error while closing connection:', err);
  } finally {
    channel = null;
    connection = null;
  }
}

module.exports = {
  publishEvent,
  closeConnection,
};

const amqp = require('amqplib');
const logger = require('../../config/logger');

const EXCHANGE_NAME = 'users.events';
const EXCHANGE_TYPE = 'topic';
const QUEUE_NAME = 'users.crud.queue';
const ROUTING_KEY = 'user.*';
const DLX_NAME = 'users.events.dlx';
const DLX_TYPE = 'direct';
const DLQ_NAME = 'users.crud.dlq';
const DLQ_ROUTING_KEY = 'users.crud.queue';

async function dispatchUserEvent(eventType, payload, userService) {
  switch (eventType) {
    case 'user.created':
      logger.info(`[UserEventsConsumer] Processing user.created event for user id: ${payload && payload.id}`);
      if (userService && typeof userService.handleUserCreatedEvent === 'function') {
        await userService.handleUserCreatedEvent(payload);
      } else {
        logger.info(`[UserEventsConsumer] user.created: no post-processing handler registered`);
      }
      break;

    case 'user.updated':
      logger.info(`[UserEventsConsumer] Processing user.updated event for user id: ${payload && payload.id}`);
      if (userService && typeof userService.invalidateUserCache === 'function') {
        await userService.invalidateUserCache(payload.id);
      } else {
        logger.info(`[UserEventsConsumer] user.updated: no cache invalidation handler registered`);
      }
      break;

    case 'user.deleted':
      logger.info(`[UserEventsConsumer] Processing user.deleted event for user id: ${payload && payload.id}`);
      if (userService && typeof userService.invalidateUserCache === 'function') {
        await userService.invalidateUserCache(payload.id);
      }
      if (userService && typeof userService.cleanupUserResources === 'function') {
        await userService.cleanupUserResources(payload.id);
      } else {
        logger.info(`[UserEventsConsumer] user.deleted: no cleanup handler registered`);
      }
      break;

    case 'user.sync_requested':
      logger.info(`[UserEventsConsumer] Processing user.sync_requested event`);
      if (userService && typeof userService.syncWithExternalServices === 'function') {
        await userService.syncWithExternalServices(payload);
      } else {
        logger.info(`[UserEventsConsumer] user.sync_requested: no sync handler registered`);
      }
      break;

    default:
      logger.warn(`[UserEventsConsumer] Unknown eventType received: ${eventType}. Acknowledging without processing.`);
      break;
  }
}

async function startUserEventsConsumer(userService) {
  const rabbitmqUrl = process.env.RABBITMQ_URL;
  const reconnectDelay = parseInt(process.env.RABBITMQ_RECONNECT_DELAY, 10) || 5000;
  const maxRetries = parseInt(process.env.RABBITMQ_MAX_RETRIES, 10) || 10;

  let retryCount = 0;

  async function connect() {
    try {
      logger.info(`[UserEventsConsumer] Attempting to connect to RabbitMQ (attempt ${retryCount + 1}/${maxRetries})`);

      const connection = await amqp.connect(rabbitmqUrl);

      retryCount = 0;

      logger.info('[UserEventsConsumer] Connection to RabbitMQ established successfully');

      connection.on('error', (err) => {
        logger.error(`[UserEventsConsumer] RabbitMQ connection error: ${err.message}`);
      });

      connection.on('close', () => {
        logger.warn('[UserEventsConsumer] RabbitMQ connection closed. Attempting reconnection...');
        scheduleReconnect();
      });

      const channel = await connection.createChannel();
      await channel.prefetch(1);

      await channel.assertExchange(EXCHANGE_NAME, EXCHANGE_TYPE, { durable: true });

      await channel.assertExchange(DLX_NAME, DLX_TYPE, { durable: true });

      await channel.assertQueue(DLQ_NAME, { durable: true });

      await channel.bindQueue(DLQ_NAME, DLX_NAME, DLQ_ROUTING_KEY);

      await channel.assertQueue(QUEUE_NAME, {
        durable: true,
        arguments: {
          'x-dead-letter-exchange': DLX_NAME,
        },
      });

      await channel.bindQueue(QUEUE_NAME, EXCHANGE_NAME, ROUTING_KEY);

      logger.info(`[UserEventsConsumer] Queue "${QUEUE_NAME}" declared and bound to exchange "${EXCHANGE_NAME}" with routing key "${ROUTING_KEY}"`);

      channel.consume(QUEUE_NAME, async (msg) => {
        if (!msg) {
          logger.warn('[UserEventsConsumer] Received null message, consumer may have been cancelled');
          return;
        }

        let parsedMessage;
        let eventType;
        let payload;

        try {
          const rawContent = msg.content.toString();
          parsedMessage = JSON.parse(rawContent);
          eventType = parsedMessage.eventType;
          payload = parsedMessage.payload;

          logger.info(`[UserEventsConsumer] Message received with eventType: ${eventType}`);

          if (process.env.NODE_ENV !== 'production') {
            logger.debug(`[UserEventsConsumer] Full payload: ${JSON.stringify(payload)}`);
          }
        } catch (parseError) {
          logger.error(`[UserEventsConsumer] Failed to parse message: ${parseError.message}`);
          channel.nack(msg, false, false);
          return;
        }

        try {
          await dispatchUserEvent(eventType, payload, userService);
          channel.ack(msg);
          logger.info(`[UserEventsConsumer] Message with eventType "${eventType}" processed and acknowledged`);
        } catch (handlerError) {
          logger.error(`[UserEventsConsumer] Error processing event "${eventType}": ${handlerError.message}`);

          const isRecoverable =
            handlerError.message &&
            (handlerError.message.toLowerCase().includes('timeout') ||
              handlerError.message.toLowerCase().includes('temporarily unavailable') ||
              handlerError.message.toLowerCase().includes('econnrefused'));

          if (isRecoverable) {
            logger.warn(`[UserEventsConsumer] Recoverable error for event "${eventType}". Re-queuing message.`);
            channel.nack(msg, false, true);
          } else {
            logger.error(`[UserEventsConsumer] Non-recoverable error for event "${eventType}". Sending to DLQ.`);
            channel.nack(msg, false, false);
          }
        }
      });

      logger.info(`[UserEventsConsumer] Consumer registered on queue "${QUEUE_NAME}"`);
    } catch (connectionError) {
      logger.error(`[UserEventsConsumer] Failed to connect to RabbitMQ: ${connectionError.message}`);
      scheduleReconnect();
    }
  }

  function scheduleReconnect() {
    retryCount += 1;

    if (retryCount > maxRetries) {
      logger.error(
        `[UserEventsConsumer] Maximum reconnection attempts (${maxRetries}) exceeded. Consumer will not restart. Manual intervention required.`
      );
      process.emit('userEventsConsumerFailed', {
        message: 'RabbitMQ consumer failed after maximum retries',
        maxRetries,
      });
      return;
    }

    logger.warn(
      `[UserEventsConsumer] Scheduling reconnection attempt ${retryCount}/${maxRetries} in ${reconnectDelay}ms`
    );

    setTimeout(() => {
      connect();
    }, reconnectDelay);
  }

  await connect();
}

module.exports = { startUserEventsConsumer };

const redisClient = require('../config/redis');
const logger = require('../config/logger');

const USER_KEY_PREFIX = 'user:';
const USERS_ALL_KEY = 'users:all';
const USER_TTL = parseInt(process.env.CACHE_USER_TTL, 10) || 3600;
const USERS_LIST_TTL = parseInt(process.env.CACHE_USERS_LIST_TTL, 10) || 300;

const sanitizeUser = (userData) => {
  if (!userData || typeof userData !== 'object') return userData;
  const sanitized = { ...userData };
  delete sanitized.password;
  return sanitized;
};

const sanitizeUsers = (usersArray) => {
  if (!Array.isArray(usersArray)) return usersArray;
  return usersArray.map((user) => sanitizeUser(user));
};

const getUserById = async (id) => {
  try {
    const key = `${USER_KEY_PREFIX}${id}`;
    const cached = await redisClient.get(key);
    if (cached) {
      logger.debug(`[users.cache] Cache HIT - getUserById id=${id}`);
      return JSON.parse(cached);
    }
    logger.debug(`[users.cache] Cache MISS - getUserById id=${id}`);
    return null;
  } catch (error) {
    logger.error(`[users.cache] Error en getUserById id=${id}: ${error.message}`);
    return null;
  }
};

const setUserById = async (id, userData) => {
  try {
    const key = `${USER_KEY_PREFIX}${id}`;
    const sanitized = sanitizeUser(userData);
    await redisClient.setex(key, USER_TTL, JSON.stringify(sanitized));
    logger.debug(`[users.cache] Usuario almacenado en caché id=${id}`);
    return true;
  } catch (error) {
    logger.error(`[users.cache] Error en setUserById id=${id}: ${error.message}`);
    return false;
  }
};

const getAllUsers = async () => {
  try {
    const cached = await redisClient.get(USERS_ALL_KEY);
    if (cached) {
      logger.debug(`[users.cache] Cache HIT - getAllUsers`);
      return JSON.parse(cached);
    }
    logger.debug(`[users.cache] Cache MISS - getAllUsers`);
    return null;
  } catch (error) {
    logger.error(`[users.cache] Error en getAllUsers: ${error.message}`);
    return null;
  }
};

const setAllUsers = async (usersArray) => {
  try {
    const sanitized = sanitizeUsers(usersArray);
    await redisClient.setex(USERS_ALL_KEY, USERS_LIST_TTL, JSON.stringify(sanitized));
    logger.debug(`[users.cache] Listado de usuarios almacenado en caché count=${sanitized.length}`);
    return true;
  } catch (error) {
    logger.error(`[users.cache] Error en setAllUsers: ${error.message}`);
    return false;
  }
};

const invalidateUserById = async (id) => {
  try {
    const key = `${USER_KEY_PREFIX}${id}`;
    await redisClient.del(key);
    await redisClient.del(USERS_ALL_KEY);
    logger.debug(`[users.cache] Caché invalidada para usuario id=${id} y listado completo`);
    return true;
  } catch (error) {
    logger.error(`[users.cache] Error en invalidateUserById id=${id}: ${error.message}`);
    return false;
  }
};

const invalidateAllUsers = async () => {
  try {
    await redisClient.del(USERS_ALL_KEY);
    logger.debug(`[users.cache] Caché del listado completo de usuarios invalidada`);
    return true;
  } catch (error) {
    logger.error(`[users.cache] Error en invalidateAllUsers: ${error.message}`);
    return false;
  }
};

const invalidateAll = async () => {
  try {
    await invalidateAllUsers();

    const pattern = `${USER_KEY_PREFIX}*`;
    let cursor = '0';
    const keysToDelete = [];

    do {
      const result = await redisClient.scan(cursor, 'MATCH', pattern, 'COUNT', 100);
      cursor = result[0];
      const keys = result[1];
      if (keys && keys.length > 0) {
        keysToDelete.push(...keys);
      }
    } while (cursor !== '0');

    if (keysToDelete.length > 0) {
      await redisClient.del(...keysToDelete);
    }

    logger.debug(`[users.cache] Limpieza total de caché de usuarios completada. Claves eliminadas: ${keysToDelete.length}`);
    return true;
  } catch (error) {
    logger.error(`[users.cache] Error en invalidateAll: ${error.message}`);
    return false;
  }
};

module.exports = {
  getUserById,
  setUserById,
  getAllUsers,
  setAllUsers,
  invalidateUserById,
  invalidateAllUsers,
  invalidateAll,
};

