 */
function generateToken(payload) {
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    throw new Error('JWT_SECRET no está definido en las variables de entorno');
  }

  const cleanPayload = {
    id: payload.id,
    email: payload.email,
    role: payload.role,
  };

  const expiresIn = process.env.JWT_EXPIRES_IN || '1h';

  return jwt.sign(cleanPayload, secret, {
    algorithm: 'HS256',
    expiresIn,
  });
}

/**
 * Verifica y decodifica un token JWT.
 * @param {string} token - Token JWT a verificar.
 * @returns {Object} Payload decodificado si el token es válido.
 * @throws {Error} Si el token es inválido, expirado o hay un error de verificación.
 */
function verifyToken(token) {
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    throw new Error('JWT_SECRET no está definido en las variables de entorno');
  }

  try {
    return jwt.verify(token, secret, {
      algorithms: ['HS256'],
    });
  } catch (error) {
    if (error instanceof jwt.TokenExpiredError) {
      throw new Error('Token expirado');
    }
    if (error instanceof jwt.JsonWebTokenError) {
      throw new Error('Token inválido');
    }
    throw new Error('Error al verificar token');
  }
}

/**
 * Decodifica un token JWT sin verificar la firma.
 * ⚠️ ADVERTENCIA: Esta función NO verifica la firma del token.
 * No debe usarse para autenticación ni para tomar decisiones de seguridad.
 * Usar únicamente para inspección cuando el token ya fue previamente validado.
 * @param {string} token - Token JWT a decodificar.
 * @returns {Object|null} Payload decodificado o null si el token es malformado.
 */
function decodeToken(token) {
  return jwt.decode(token);
}

module.exports = {
  generateToken,
  verifyToken,
  decodeToken,
};

const bcrypt = require('bcrypt');

const SALT_ROUNDS = parseInt(process.env.BCRYPT_SALT_ROUNDS, 10) || 12;

async function hashPassword(plainPassword) {
  if (plainPassword === null || plainPassword === undefined || plainPassword === '') {
    throw new Error('Password is required and must be a non-empty string');
  }
  if (typeof plainPassword !== 'string') {
    throw new Error('Password must be a string');
  }
  const hash = await bcrypt.hash(plainPassword, SALT_ROUNDS);
  return hash;
}

async function comparePassword(plainPassword, hashedPassword) {
  if (
    !plainPassword ||
    !hashedPassword ||
    typeof plainPassword !== 'string' ||
    typeof hashedPassword !== 'string'
  ) {
    throw new Error('Both plainPassword and hashedPassword are required');
  }
  const result = await bcrypt.compare(plainPassword, hashedPassword);
  return result;
}

module.exports = {
  hashPassword,
  comparePassword,
};

const HTTP_STATUS = {
  OK: 200,
  CREATED: 201,
  NO_CONTENT: 204,
  BAD_REQUEST: 400,
  UNAUTHORIZED: 401,
  FORBIDDEN: 403,
  NOT_FOUND: 404,
  CONFLICT: 409,
  UNPROCESSABLE_ENTITY: 422,
  TOO_MANY_REQUESTS: 429,
  INTERNAL_SERVER_ERROR: 500,
  SERVICE_UNAVAILABLE: 503,
};

function sendSuccess(req, res, message, data = null, statusCode = 200, meta = null) {
  const payload = {
    success: true,
    message,
    data,
    timestamp: new Date().toISOString(),
    path: req.originalUrl,
  };

  if (meta !== null && meta !== undefined) {
    payload.meta = meta;
  }

  res.status(statusCode).json(payload);
}

function sendError(req, res, message, statusCode = 500, errors = null) {
  const payload = {
    success: false,
    message,
    data: null,
    timestamp: new Date().toISOString(),
    path: req.originalUrl,
  };

  if (errors !== null && errors !== undefined) {
    payload.errors = errors;
  }

  res.status(statusCode).json(payload);
}

function sendPaginated(req, res, message, data, total, page, limit) {
  const totalPages = Math.ceil(total / limit);
  const hasNextPage = page < totalPages;
  const hasPrevPage = page > 1;

  const meta = {
    total,
    page,
    limit,
    totalPages,
    hasNextPage,
    hasPrevPage,
  };

  sendSuccess(req, res, message, data, 200, meta);
}

module.exports = {
  HTTP_STATUS,
  sendSuccess,
  sendError,
  sendPaginated,
};

const winston = require('winston');
const fs = require('fs');
const path = require('path');

// NOTE: Security responsibility - callers must sanitize sensitive data before logging.
// Never pass passwords, full JWT tokens, or sensitive user fields as metadata to this logger.
// The logger does NOT sanitize incoming metadata objects.

const NODE_ENV = process.env.NODE_ENV || 'production';
const SERVICE_NAME = process.env.SERVICE_NAME || 'api-service';

const getLogLevel = () => {
  if (process.env.LOG_LEVEL) {
    return process.env.LOG_LEVEL;
  }
  switch (NODE_ENV) {
    case 'development':
      return 'debug';
    case 'test':
      return 'error';
    default:
      return 'http';
  }
};

const devConsoleFormat = winston.format.combine(
  winston.format.colorize({ all: true }),
  winston.format.timestamp({ format: 'YYYY-MM-DD HH:mm:ss.SSS' }),
  winston.format.errors({ stack: true }),
  winston.format.printf(({ timestamp, level, message, stack, correlationId, ...meta }) => {
    let log = `${timestamp} [${level.toUpperCase()}]`;
    if (correlationId) {
      log += ` [correlationId=${correlationId}]`;
    }
    log += ` ${message}`;
    if (stack) {
      log += `\n${stack}`;
    }
    const remainingMeta = Object.keys(meta).filter(
      k => !['service', 'environment', 'level', 'timestamp'].includes(k)
    );
    if (remainingMeta.length > 0) {
      const metaObj = {};
      remainingMeta.forEach(k => { metaObj[k] = meta[k]; });
      log += ` ${JSON.stringify(metaObj)}`;
    }
    return log;
  })
);

const jsonFormat = winston.format.combine(
  winston.format.timestamp({ format: 'YYYY-MM-DDTHH:mm:ss.SSSZ' }),
  winston.format.errors({ stack: true }),
  winston.format.json()
);

const buildTransports = () => {
  const transports = [];

  const consoleFormat = NODE_ENV === 'development' ? devConsoleFormat : jsonFormat;

  transports.push(
    new winston.transports.Console({
      format: consoleFormat,
    })
  );

  if (NODE_ENV === 'production') {
    const logsDir = path.join(process.cwd(), 'logs');
    fs.mkdirSync(logsDir, { recursive: true });

    let DailyRotateFile;
    try {
      DailyRotateFile = require('winston-daily-rotate-file');
    } catch (e) {
      // winston-daily-rotate-file not available, skip file transports
      DailyRotateFile = null;
    }

    if (DailyRotateFile) {
      transports.push(
        new DailyRotateFile({
          filename: path.join(logsDir, 'error.log'),
          datePattern: 'YYYY-MM-DD',
          level: 'error',
          maxFiles: '14d',
          maxSize: '20m',
          format: jsonFormat,
          zippedArchive: true,
        })
      );

      transports.push(
        new DailyRotateFile({
          filename: path.join(logsDir, 'combined.log'),
          datePattern: 'YYYY-MM-DD',
          level: 'http',
          maxFiles: '14d',
          maxSize: '20m',
          format: jsonFormat,
          zippedArchive: true,
        })
      );
    }
  }

  return transports;
};

const logger = winston.createLogger({
  level: getLogLevel(),
  silent: NODE_ENV === 'test',
  defaultMeta: {
    service: SERVICE_NAME,
    environment: NODE_ENV,
  },
  format: winston.format.combine(
    winston.format.errors({ stack: true }),
    winston.format.timestamp({ format: 'YYYY-MM-DDTHH:mm:ss.SSSZ' })
  ),
  transports: buildTransports(),
});

module.exports = logger;

